(()=>{const grid=document.querySelector('#homeTrendGrid');if(!grid)return;const fallback=[{title:'One Piece',meta:'Aventure · Action · Épisodes en cours',tone:'violet'},{title:'Solo Leveling',meta:'Action · Fantasy · Montée en puissance',tone:'pink'},{title:'Frieren',meta:'Fantasy · Voyage · Émotions',tone:'cyan'},{title:'The Apothecary Diaries',meta:'Mystère · Romance · Palais',tone:'gold'}],safe=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char])),title=item=>item.title?.english||item.title?.romaji||item.title?.native||'Anime à découvrir',renderFallback=()=>{grid.innerHTML=fallback.map((item,index)=>'<a class="home-trend-card fallback '+item.tone+'" href="#tendance"><span class="home-trend-rank">0'+(index+1)+'</span><div><b>'+item.title+'</b><small>'+item.meta+'</small></div><i>→</i></a>').join('')},render=items=>{grid.innerHTML=items.map((item,index)=>'<button class="home-trend-card" type="button" data-home-anime="'+Number(item.id)+'"><span class="home-trend-rank">0'+(index+1)+'</span><span class="home-trend-cover">'+(item.coverImage?.large?'<img src="'+safe(item.coverImage.large)+'" alt="">':'✦')+'</span><span><b>'+safe(title(item))+'</b><small>'+safe((item.genres||[]).slice(0,2).join(' · ')||'Tendance anime')+'</small></span><i>→</i></button>').join('')};grid.addEventListener('click',event=>{const card=event.target.closest('[data-home-anime]');if(!card)return;if(typeof openEnriched==='function')openEnriched(card.dataset.homeAnime);else location.hash='tendance'});document.querySelector('.home-trend-themes')?.addEventListener('click',event=>{const link=event.target.closest('[data-home-genre]');if(!link)return;const genre=link.dataset.homeGenre;setTimeout(()=>{const target=[...document.querySelectorAll('#moodGrid button')].find(button=>button.dataset.genre===genre);target?.click()},40)});const query='query{Page(page:1,perPage:4){media(sort:TRENDING_DESC,type:ANIME,isAdult:false){id title{romaji english native} genres coverImage{large}}}}';fetch('https://graphql.anilist.co',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({query})}).then(response=>response.ok?response.json():Promise.reject()).then(payload=>{const items=payload.data?.Page?.media||[];items.length?render(items):renderFallback()}).catch(renderFallback)})();
